import {createStructuredConsumerAdapter} from './adapters/structured-documents.js';
import {STRUCTURE_TREE,FIXTURES,NOTE_FIXTURES} from './adapters/library-fixtures.js';
import {StructuredNavigationDescriptorOwner,structuredNavigationDescriptorPolicy,setStructuredNavigationHeadingEligibility,setStructuredNavigationToggleEligibility,restoreStructuredNavigationDescriptorPolicy} from './foundation/structured/outline-descriptor.js';

const bundle={initialDocumentId:'KU-D05-0021',STRUCTURE_TREE,FIXTURES,NOTE_FIXTURES};
const assert=(condition,message)=>{if(!condition)throw Error(message)};
const run=(id,fn)=>{try{return {id,status:'PASS',evidence:fn()}}catch(error){return {id,status:'FAIL',error:String(error?.stack||error)}}};
const owners=()=>{const library=createStructuredConsumerAdapter('library',bundle),learn=createStructuredConsumerAdapter('learn');return {library,learn,libraryNav:new StructuredNavigationDescriptorOwner({adapter:library}),learnNav:new StructuredNavigationDescriptorOwner({adapter:learn})}};
const noKey=(value,key)=>{let found=false;const walk=v=>{if(found||v==null)return;if(Array.isArray(v)){for(const x of v)walk(x);return}if(typeof v==='object'){for(const [k,x] of Object.entries(v)){if(k.toLowerCase()===key.toLowerCase()){found=true;return}walk(x)}}};walk(value);return !found};

export function runW5BStructuredNavigationProof(){
  const originalPolicy=structuredNavigationDescriptorPolicy(),cases=[];
  try{
    cases.push(run('w5b.real-library-learn-descriptor-owner',()=>{const {library,learn,libraryNav,learnNav}=owners(),ld=libraryNav.descriptor(),nd=learnNav.descriptor();assert(ld.owner==='StructuredNavigationDescriptorOwner'&&nd.owner===ld.owner,'descriptor owner not shared');assert(ld.outline.canonicalTreeOwner==='StructuredTreeKernel'&&nd.outline.canonicalTreeOwner==='StructuredTreeKernel','canonical tree owner missing');assert(library.snapshot().id==='KU-D05-0021'&&learn.snapshot().id==='learn-document-trust-boundaries','real consumers not used');return {library:{documentId:library.snapshot().id,owner:ld.owner,outlineCount:ld.outline.count,quickJumpCount:ld.quickJump.count},learn:{documentId:learn.snapshot().id,owner:nd.owner,outlineCount:nd.outline.count,quickJumpCount:nd.quickJump.count},treeOwner:ld.outline.canonicalTreeOwner};}));
    cases.push(run('w5b.deterministic-canonical-outline-hierarchy',()=>{const {libraryNav}=owners(),a=libraryNav.outline(),b=libraryNav.outline();assert(JSON.stringify(a)===JSON.stringify(b),'outline derivation not deterministic');const h=a.entries.find(x=>x.target.blockId==='blk-d05-h1'),t1=a.entries.find(x=>x.target.blockId==='blk-d05-t1'),t2=a.entries.find(x=>x.target.blockId==='blk-d05-t2'),nested=a.entries.find(x=>x.target.blockId==='blk-d05-t2-n1');assert(h?.kind==='heading'&&h.headingRank===2,'h2 missing');assert(t1?.outlineParentTarget?.blockId==='blk-d05-h1'&&t2?.outlineParentTarget?.blockId==='blk-d05-h1','top toggles not parented under canonical outline heading');assert(nested?.outlineParentTarget?.blockId==='blk-d05-t2','nested toggle hierarchy false');assert(nested.canonical.parentBlockId==='blk-d05-t2'&&nested.canonical.pathBlockIds.join('/')==='blk-d05-t2/blk-d05-t2-n1','canonical nested identity false');return {deterministic:true,root:a.hierarchy.map(x=>x.target.blockId),nestedParent:nested.outlineParentTarget.blockId,nestedCanonicalPath:nested.canonical.pathBlockIds};}));
    cases.push(run('w5b.heading-toggle-eligibility-truthful-labels',()=>{const {libraryNav,learnNav}=owners(),l=libraryNav.outline(),n=learnNav.outline(),ids=l.entries.map(x=>x.target.blockId),h=l.entries.find(x=>x.target.blockId==='blk-d05-h1'),toggle=l.entries.find(x=>x.target.blockId==='blk-d05-t1');assert(ids.includes('blk-d05-h1')&&ids.includes('blk-d05-t1')&&!ids.includes('blk-d05-p1'),'eligibility policy false');assert(h.label==='نطاق الحماية في واجهات API'&&h.labelSource==='content','heading label false');assert(toggle.label==='01 — التحقق من هوية المورد'&&toggle.labelSource==='content','toggle label false');assert(n.entries.length===1&&n.entries[0].target.blockId==='learn-h1'&&n.entries[0].label==='حدود الثقة والتحقق','Learn heading truth false');return {policy:structuredNavigationDescriptorPolicy(),libraryEligible:ids,headingLabel:h.label,toggleLabel:toggle.label,learnEligible:n.entries.map(x=>x.target.blockId)};}));
    cases.push(run('w5b.central-toggle-eligibility-governs-outline-and-quick-jump',()=>{const {libraryNav}=owners(),beforeOutline=libraryNav.outline(),beforeQuick=libraryNav.quickJump(),change=setStructuredNavigationToggleEligibility(false),duringOutline=libraryNav.outline(),duringQuick=libraryNav.quickJump();assert(beforeOutline.entries.some(x=>x.kind==='toggle')&&beforeQuick.items.some(x=>x.kind==='toggle'),'baseline toggle eligibility missing');assert(!duringOutline.entries.some(x=>x.kind==='toggle')&&!duringQuick.items.some(x=>x.kind==='toggle'),'central toggle eligibility change not applied');const reverted=change.revert(),afterOutline=libraryNav.outline(),afterQuick=libraryNav.quickJump();assert(JSON.stringify(afterOutline)===JSON.stringify(beforeOutline)&&JSON.stringify(afterQuick)===JSON.stringify(beforeQuick),'toggle eligibility exact revert false');return {beforeToggleCount:beforeOutline.entries.filter(x=>x.kind==='toggle').length,duringToggleCount:duringOutline.entries.filter(x=>x.kind==='toggle').length,reverted,exactRevert:true};}));
    cases.push(run('w5b.read-inspection-no-selection-focus-or-mutation',()=>{const {learn,learnNav}=owners(),beforeDoc=JSON.stringify(learn.snapshot()),beforeTx=JSON.stringify(learn.transactionDescriptor()),beforeSelection=JSON.stringify(learn.selection.descriptor()),receiptCount=learn.selection.receipts().length,descriptor=learnNav.readInspection('learn-p1',{mode:'read'}),afterSelection=JSON.stringify(learn.selection.descriptor());assert(descriptor.eligible&&descriptor.target.blockId==='learn-p1','inspection descriptor unavailable');assert(descriptor.behavior.activatesEditSelection===false&&descriptor.behavior.capturesWriterFocus===false,'inspection claims focus/selection ownership');assert(beforeDoc===JSON.stringify(learn.snapshot())&&beforeTx===JSON.stringify(learn.transactionDescriptor()),'read inspection mutated document/transaction truth');assert(beforeSelection===afterSelection&&learn.selection.receipts().length===receiptCount,'read inspection touched selection owner');return {target:descriptor.target,behavior:descriptor.behavior,selectionUnchanged:true,documentUnchanged:true,transactionUnchanged:true};}));
    cases.push(run('w5b.quick-jump-canonical-identity-never-dom',()=>{const {libraryNav}=owners(),q=libraryNav.quickJump(),item=q.items.find(x=>x.target.blockId==='blk-d05-t2-n1');assert(item&&item.target.documentId==='KU-D05-0021'&&item.target.identityKind==='canonical-structured-block','canonical target identity false');assert(q.domIdentityCanonical===false&&q.performsDomScroll===false&&item.request.performsDomScroll===false,'DOM scroll/identity ownership leaked');assert(noKey(q,'domId')&&noKey(q,'elementId')&&noKey(q,'selector'),'DOM identity leaked into descriptor truth');return {target:item.target,domIdentityCanonical:q.domIdentityCanonical,performsDomScroll:q.performsDomScroll,forbiddenDomKeysAbsent:true};}));
    cases.push(run('w5b.global-transient-and-context-lifecycle-delegation',()=>{const {libraryNav}=owners(),d=libraryNav.descriptor(),p=d.presentationDelegation;assert(p.transientPresentationOwner==='TransientFocusOwner'&&p.contextInspectorLifecycleOwner==='ContextInspectorHost','presentation owner delegation false');assert(!p.descriptorOwnerOwnsTransientLifecycle&&!p.descriptorOwnerOwnsDomScroll&&!p.descriptorOwnerOwnsSelection&&!p.descriptorOwnerOwnsDocumentMutation&&!p.descriptorOwnerOwnsDomainReferenceMutation,'descriptor owner over-claims lifecycle/mutation');return p;}));
    cases.push(run('w5b.central-heading-policy-library-learn-exact-revert',()=>{const {libraryNav,learnNav}=owners(),policyBefore=structuredNavigationDescriptorPolicy(),libraryBefore=JSON.stringify(libraryNav.descriptor()),learnBefore=JSON.stringify(learnNav.descriptor()),change=setStructuredNavigationHeadingEligibility(['h3']),libraryDuring=libraryNav.descriptor(),learnDuring=learnNav.descriptor();assert(!libraryDuring.outline.entries.some(x=>x.kind==='heading'&&x.target.blockId==='blk-d05-h1'),'Library central heading change not observed');assert(!learnDuring.outline.entries.some(x=>x.kind==='heading'&&x.target.blockId==='learn-h1'),'Learn central heading change not observed');const reverted=change.revert(),libraryAfter=JSON.stringify(libraryNav.descriptor()),learnAfter=JSON.stringify(learnNav.descriptor());assert(JSON.stringify(policyBefore)===JSON.stringify(reverted),'policy exact revert false');assert(libraryAfter===libraryBefore&&learnAfter===learnBefore,'descriptor exact revert false');return {before:policyBefore,during:change.current,reverted,libraryChanged:true,learnChanged:true,libraryExactRevert:libraryAfter===libraryBefore,learnExactRevert:learnAfter===learnBefore};}));
    cases.push(run('w5b.negative-domain-mutation-and-owner-boundary',()=>{const {library,learn,libraryNav,learnNav}=owners(),before={library:JSON.stringify(library.snapshot()),learn:JSON.stringify(learn.snapshot()),libraryTx:JSON.stringify(library.transactionDescriptor()),learnTx:JSON.stringify(learn.transactionDescriptor())};libraryNav.descriptor();libraryNav.readInspection('blk-d05-t1');learnNav.descriptor();learnNav.readInspection('learn-h1');const after={library:JSON.stringify(library.snapshot()),learn:JSON.stringify(learn.snapshot()),libraryTx:JSON.stringify(library.transactionDescriptor()),learnTx:JSON.stringify(learn.transactionDescriptor())};assert(JSON.stringify(before)===JSON.stringify(after),'descriptor derivation mutated domain/transaction truth');assert(library.mutationKernel.owner==='StructuredMutationKernel'&&learn.mutationKernel.owner==='StructuredMutationKernel','canonical mutation owner altered');assert(library.selection.owner==='StructuredSelectionKernel'&&learn.selection.owner==='StructuredSelectionKernel','canonical selection owner altered');return {unchanged:true,mutationOwner:library.mutationKernel.owner,selectionOwner:library.selection.owner,descriptorOwner:libraryNav.owner};}));
  }finally{restoreStructuredNavigationDescriptorPolicy(originalPolicy)}
  const pass=cases.filter(x=>x.status==='PASS').length,fail=cases.length-pass;
  return {schemaVersion:1,kind:'W5_B_STRUCTURED_NAVIGATION_DESCRIPTOR_OWNER_PROOF',status:fail?'FAIL':'PASS',pass,fail,cases,finalPolicy:structuredNavigationDescriptorPolicy()};
}
